using System.Windows;
using System.Windows.Automation;
using System.Windows.Automation.Peers;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Input;
using System.Windows.Media;
using Humcp.Schema;

namespace Humcp.App;

/// <summary>
/// A form whose schema is humcp's own — a server's settings, the box a configuration is pasted
/// into — generated by the same <see cref="FormBuilder"/>, bound to the same templates and filled in
/// through the same <see cref="FormState"/> as every tool's (ROADMAP §10, Phase 6).
/// </summary>
/// <remarks>
/// <para>
/// Two things differ from a tool form, and both because the schema is ours. <b>Nothing is
/// hidden</b>: every field here is saved whether or not it was looked at, which is §7.31's rule for
/// a question window for the same reason. And <b>a problem blocks the save</b>: §5's "never block on
/// client validation" defers to a server that knows what it accepts, and here there is no server.
/// </para>
/// <para>
/// Non-modal and tracked like every other window (§8); <kbd>Escape</kbd>, <kbd>Ctrl</kbd>+<kbd>W</kbd>
/// and the Cancel button close it without saving.
/// </para>
/// </remarks>
internal sealed class OwnFormWindow : Window
{
    /// <summary>The letters this window's own chrome takes: the Form and Window menus, Save and Cancel.</summary>
    public static readonly IReadOnlyList<char> Reserved = ['f', 'w', 's', 'c'];

    private readonly FormState _state;
    private readonly WindowManager _windows;
    private readonly string _prefix;
    private readonly string _saveLabel;
    private readonly Func<FormState, Task<string?>> _save;

    private readonly FormItemsControl _fields = new();
    private readonly ListBox _problems = new();
    private readonly DockPanel _problemsPane = new();
    private readonly TextBlock _problemsHeading = new();
    private readonly TextBlock _status = new();

    private bool _saving;

    /// <param name="prefix">
    /// Put in front of every automation id. An owned window is a UIA descendant of its owner, and
    /// two of these can be open at once, so an id is unique across the process or it is a coin toss
    /// (§9, phase3-notes 4.3).
    /// </param>
    /// <param name="saveLabel">The verb on the button, without an access key: "Save", "Import".</param>
    /// <param name="fill">Puts the current values in the boxes, after the state exists and before it is shown.</param>
    /// <param name="save">
    /// Does whatever saving means. Answers null to close the window, or a sentence saying why not,
    /// which is announced and leaves everything as the user typed it.
    /// </param>
    public OwnFormWindow(
        Window owner,
        string title,
        string prefix,
        FormModel form,
        string saveLabel,
        WindowManager windows,
        Action<FormState>? fill,
        Func<FormState, Task<string?>> save)
    {
        ArgumentNullException.ThrowIfNull(form);
        ArgumentNullException.ThrowIfNull(windows);
        ArgumentNullException.ThrowIfNull(save);

        _windows = windows;
        _prefix = prefix;
        _saveLabel = saveLabel;
        _save = save;

        _state = FormState.Create(form, Reserved);
        _state.ShowOptional = true;
        fill?.Invoke(_state);

        Title = title;
        Owner = owner;
        Width = 640;
        Height = 600;
        MinWidth = 440;
        WindowStartupLocation = WindowStartupLocation.CenterOwner;

        // §7.17: a WPF Window is a ContentControl, and with no name of its own it announces the
        // whole of its content as its name.
        AutomationProperties.SetName(this, title);

        DataContext = _state;
        Content = Build();

        _windows.Track(this);
        Bind();

        Loaded += (_, _) =>
        {
            SetStatus($"{title}. {Count(_state.Fields.Count, "field", "fields")}, {_state.RequiredCount} required. " +
                      "Control plus Enter saves.");

            // Unlike a question, there is no message to read first: the fields are the content.
            if (!Focus(_state.Fields.FirstOrDefault())) _fields.Focus();
        };
    }

    // ------------------------------------------------------------------ the window

    private UIElement Build()
    {
        var layout = new DockPanel();

        var menu = new MenuItem { Header = "_Form" };
        menu.Items.Add(new MenuItem { Header = "_" + _saveLabel, Command = FormCommands.Submit, InputGestureText = "Ctrl+Enter" });
        menu.Items.Add(new MenuItem { Header = "_Cancel", Command = WindowManager.CloseWindow, InputGestureText = "Esc" });
        menu.Items.Add(new Separator());
        menu.Items.Add(new MenuItem { Header = "Detai_ls of this field", Command = FormCommands.Details, InputGestureText = "F1" });

        var bar = _windows.CreateMenuBar(this, closable: true, menu);
        DockPanel.SetDock(bar, Dock.Top);
        layout.Children.Add(bar);

        // Not focusable, for the reason every status bar here is not (§7.14).
        var statusBar = new StatusBar { Focusable = false, IsTabStop = false };
        DockPanel.SetDock(statusBar, Dock.Bottom);

        // A polite live region with no name of its own: a TextBlock's accessible name is its text,
        // so naming it would make every announcement say the label instead of the message (§7.16).
        _status.TextWrapping = TextWrapping.Wrap;
        AutomationProperties.SetAutomationId(_status, _prefix + "Status");
        AutomationProperties.SetLiveSetting(_status, AutomationLiveSetting.Polite);
        statusBar.Items.Add(new StatusBarItem { Content = _status });
        layout.Children.Add(statusBar);

        var body = new Grid { Margin = new Thickness(10, 10, 10, 0) };
        body.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
        body.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
        body.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

        body.Children.Add(Fields());
        body.Children.Add(Problems());
        body.Children.Add(Buttons());

        layout.Children.Add(body);
        return layout;
    }

    private UIElement Fields()
    {
        var pane = new DockPanel();
        Grid.SetRow(pane, 0);

        _fields.ItemsSource = _state.VisibleFields;
        _fields.ItemTemplateSelector = new FieldTemplateSelector();
        AutomationProperties.SetName(_fields, Title);
        AutomationProperties.SetAutomationId(_fields, _prefix + "Fields");

        // Focusable false, like every other scroll viewer here: WPF makes one a tab stop the moment
        // it has something to scroll, and a scroll viewer is not a control (§7.14).
        pane.Children.Add(new ScrollViewer
        {
            Content = _fields,
            Focusable = false,
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled,
            Padding = new Thickness(0, 0, 12, 0),
        });

        return pane;
    }

    private UIElement Problems()
    {
        Grid.SetRow(_problemsPane, 1);
        _problemsPane.Visibility = Visibility.Collapsed;
        _problemsPane.Margin = new Thickness(0, 8, 0, 0);

        _problemsHeading.Text = "Problems";
        _problemsHeading.FontWeight = FontWeights.Bold;
        _problemsHeading.Margin = new Thickness(0, 0, 0, 4);
        AutomationProperties.SetHeadingLevel(_problemsHeading, AutomationHeadingLevel.Level2);
        DockPanel.SetDock(_problemsHeading, Dock.Top);
        _problemsPane.Children.Add(_problemsHeading);

        _problems.MaxHeight = 110;
        AutomationProperties.SetName(_problems, "Problems");
        AutomationProperties.SetAutomationId(_problems, _prefix + "Problems");
        AutomationProperties.SetHelpText(_problems,
            "Arrow through the problems. Enter moves to the field one is about.");

        _problems.InputBindings.Add(new KeyBinding(FormCommands.GoToProblem, new KeyGesture(Key.Enter))
        {
            CommandParameter = _problems,
        });

        _problemsPane.Children.Add(_problems);
        return _problemsPane;
    }

    private UIElement Buttons()
    {
        var row = new StackPanel { Orientation = Orientation.Horizontal, Margin = new Thickness(0, 10, 0, 8) };
        Grid.SetRow(row, 2);

        row.Children.Add(Button(_prefix + "Save", "_" + _saveLabel, FormCommands.Submit, "Control plus Enter",
            $"{_saveLabel}s what is on this form. Control plus Enter does the same."));

        row.Children.Add(Button(_prefix + "Cancel", "_Cancel", WindowManager.CloseWindow, "Escape",
            "Closes this window without saving. Escape does the same."));

        return row;
    }

    private static Button Button(string id, string content, RoutedUICommand command, string accelerator, string help)
    {
        var button = new Button
        {
            Content = content,
            Command = command,
            Padding = new Thickness(14, 4, 14, 4),
            Margin = new Thickness(0, 0, 8, 0),
        };

        AutomationProperties.SetAutomationId(button, id);

        // Set here rather than left to WPF, which would announce the command's own Text in the slot
        // a screen reader uses for the shortcut (§7.27), and spelled out because it is spoken (§7.15).
        AutomationProperties.SetAcceleratorKey(button, accelerator);
        AutomationProperties.SetHelpText(button, help);

        return button;
    }

    // ------------------------------------------------------------------ saving

    private void Bind()
    {
        CommandBindings.Add(new CommandBinding(FormCommands.Submit, async (_, _) => await SaveAsync(),
            (_, e) => e.CanExecute = !_saving));

        CommandBindings.Add(new CommandBinding(FormCommands.Details, (_, _) => ShowDetails()));

        // The commands the field templates raise. Without them a list's Add button is disabled, and
        // a disabled button is not in the tab order at all (phase5-notes 4.9).
        FormCommandBindings.Attach(this, _state.Fields, SetStatus, _windows);

        CommandBindings.Add(new CommandBinding(FormCommands.GoToProblem, (_, e) =>
        {
            if (e.Parameter is ListBox { SelectedItem: ProblemEntry problem }) GoTo(problem);
        }, (_, e) => e.CanExecute = e.Parameter is ListBox { SelectedItem: ProblemEntry }));

        // Taken before the focused control sees it: a WPF Button handles Enter without looking at
        // the modifiers, so Ctrl+Enter on a list's own Add button would press Add (phase3-notes 4.7).
        PreviewKeyDown += async (_, e) =>
        {
            if (e.Key is not (Key.Enter or Key.Return)) return;
            if ((Keyboard.Modifiers & ModifierKeys.Control) != ModifierKeys.Control) return;

            e.Handled = true;
            await SaveAsync();
        };
    }

    private async Task SaveAsync()
    {
        if (_saving) return;

        var submission = _state.Prepare();
        ShowProblems(submission);

        if (!submission.CanSend || submission.HasIssues)
        {
            var count = submission.Build.Problems.Count + submission.Report.Issues.Count;
            var first = submission.Build.Problems.Count > 0
                ? $"{submission.Build.Problems[0].Label}: {submission.Build.Problems[0].Message}"
                : _state.LeadProblem(submission);

            SetStatus($"{Count(count, "problem", "problems")} to fix before this can be saved. {first}");
            Focus(_state.FirstProblem);
            return;
        }

        _saving = true;
        CommandManager.InvalidateRequerySuggested();

        try
        {
            if (await _save(_state) is { } refusal)
            {
                SetStatus(refusal);
                return;
            }
        }
        finally
        {
            _saving = false;
            CommandManager.InvalidateRequerySuggested();
        }

        Close();
    }

    private void ShowProblems(FormSubmission submission)
    {
        var entries = new List<ProblemEntry>();

        foreach (var problem in submission.Build.Problems)
            entries.Add(new ProblemEntry($"{problem.Label}: {problem.Message}", problem.FieldPath));

        foreach (var issue in submission.Report.Issues)
            entries.Add(new ProblemEntry(issue.Announcement, issue.FieldPath));

        _problems.ItemsSource = entries;
        _problemsPane.Visibility = entries.Count == 0 ? Visibility.Collapsed : Visibility.Visible;
        _problemsHeading.Text = $"Problems — {entries.Count}";
    }

    private void GoTo(ProblemEntry problem)
    {
        if (Focus(_state.Find(problem.FieldPath))) return;
        SetStatus("That problem is not about a field on this form.");
    }

    // ------------------------------------------------------------------ focus and announcements

    private bool Focus(FieldState? field)
    {
        if (field is null) return false;

        _fields.UpdateLayout();

        var wanted = field.SelfAndDescendants().ToHashSet();

        foreach (var element in Descendants(_fields))
        {
            if (element is not Control { Focusable: true, IsEnabled: true, Visibility: Visibility.Visible } control)
                continue;

            if (control.DataContext is not FieldState carried || !wanted.Contains(carried)) continue;

            control.BringIntoView();
            control.Focus();
            return true;
        }

        return false;
    }

    private static IEnumerable<DependencyObject> Descendants(DependencyObject root)
    {
        var count = VisualTreeHelper.GetChildrenCount(root);

        for (var i = 0; i < count; i++)
        {
            var child = VisualTreeHelper.GetChild(root, i);

            yield return child;

            foreach (var descendant in Descendants(child)) yield return descendant;
        }
    }

    private void ShowDetails()
    {
        if ((Keyboard.FocusedElement as FrameworkElement)?.DataContext is FieldState field)
        {
            TextWindow.Show(this, $"Details: {field.Label}", FieldDetails.Describe(field), _windows);
            return;
        }

        SetStatus("Move to a field first. F1 describes the field the caret is in.");
    }

    public void SetStatus(string text)
    {
        LiveRegion.Say(_status, text);
    }

    private static string Count(int count, string singular, string plural) =>
        $"{count} {(count == 1 ? singular : plural)}";
}
